import React from 'react';
import {
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  View,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { useTranslation } from 'react-i18next';
import { colors, fontFamily, fontSize, layout, shadows } from '../theme';

type Props = {
  children: React.ReactNode;
  back?: () => void;
  title?: string;
  noHeader?: boolean;
};

export function ScreenShell({ children, back, title, noHeader = false }: Props) {
  const { t } = useTranslation();
  return (
    <SafeAreaView style={styles.safe} edges={['top', 'left', 'right']}>
      {!noHeader && (
        <View style={styles.header}>
          {back ? (
            <Pressable
              accessibilityRole="button"
              onPress={back}
              style={styles.backBtn}
              hitSlop={{ top: 12, bottom: 12, left: 12, right: 12 }}
            >
              <Text style={styles.backText}>{t('actions.back')}</Text>
            </Pressable>
          ) : (
            <View style={styles.backPlaceholder} />
          )}
          {title ? (
            <Text style={styles.headerTitle} numberOfLines={1}>
              {title}
            </Text>
          ) : null}
          <View style={styles.backPlaceholder} />
        </View>
      )}
      <ScrollView
        contentContainerStyle={styles.scroll}
        keyboardShouldPersistTaps="handled"
        showsVerticalScrollIndicator={false}
      >
        {children}
      </ScrollView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: {
    flex: 1,
    backgroundColor: colors.bg,
  },
  header: {
    alignItems: 'center',
    backgroundColor: colors.surface,
    borderBottomColor: colors.border,
    borderBottomWidth: 1,
    flexDirection: 'row',
    justifyContent: 'space-between',
    minHeight: 52,
    paddingHorizontal: layout.screenHorizontalPadding,
    paddingVertical: 6,
  },
  backBtn: {
    alignItems: 'center',
    flexDirection: 'row',
    gap: 2,
    minWidth: 64,
  },
  backText: {
    color: colors.textPrimary,
    fontFamily,
    fontSize: fontSize.sm,
    fontWeight: '700',
  },
  backPlaceholder: {
    minWidth: 64,
  },
  headerTitle: {
    color: colors.textPrimary,
    flex: 1,
    fontFamily,
    fontSize: fontSize.md,
    fontWeight: '800',
    textAlign: 'center',
  },
  scroll: {
    flexGrow: 1,
    gap: layout.sectionGap,
    padding: layout.screenHorizontalPadding,
    paddingBottom: 28,
  },
});
